"""Server-rendered shells for Giraffe's Quiet Authority paper-trading UX."""
from pathlib import Path

from .config import SIGNUP_ENABLED

AUTH_HTML = r'''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Giraffe · 로그인</title><style>
:root{--graphite:#161b25;--porcelain:#f4f6f8;--sheet:#fff;--ink:#1d2735;--ink-low:#667286;--divider:#d8dee8;--cobalt:#2457d6;--cobalt-low:#edf2ff;--danger:#b9382f;--radius:14px;--shadow:0 14px 34px rgba(22,27,37,.10)}*{box-sizing:border-box}html{background:var(--porcelain);color:var(--ink);font:16px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{margin:0}.auth-layout{min-height:100dvh;display:grid;grid-template-columns:minmax(0,1fr);place-items:center;padding:24px}.auth-shell{width:min(100%,940px);display:grid;grid-template-columns:minmax(0,1.1fr) minmax(320px,.9fr);background:var(--sheet);border:1px solid var(--divider);box-shadow:var(--shadow)}.office-intro{background:var(--graphite);color:#fff;padding:40px;display:flex;flex-direction:column;justify-content:space-between;min-height:500px}.brand{display:flex;align-items:center;gap:10px;font-size:1.125rem;font-weight:800;letter-spacing:-.02em}.mark{display:grid;place-items:center;width:28px;height:28px;background:var(--cobalt);color:#fff;font-size:.8rem}.kicker{color:#aebbd0;font-size:.75rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase;margin:0 0 12px}.office-intro h1{margin:0;font-size:clamp(2rem,4vw,3.3rem);line-height:1.12;letter-spacing:-.055em}.office-intro p{max-width:32rem;color:#ced6e4}.office-facts{border-top:1px solid rgba(255,255,255,.22);padding-top:18px;color:#d9e1ed;font-size:.875rem}.auth-card{padding:40px}.auth-card h2{font-size:1.5rem;letter-spacing:-.035em;margin:0 0 6px}.muted{margin:0;color:var(--ink-low)}.paper-note{border-left:3px solid var(--cobalt);background:var(--cobalt-low);padding:12px 14px;font-size:.875rem;margin:24px 0}.auth-mode{display:flex;gap:8px;margin:22px 0}.mode-button{flex:1}.mode-button[aria-pressed="true"]{border-color:var(--cobalt);background:var(--cobalt-low);color:var(--cobalt)}button,input{font:inherit}button{min-height:44px;cursor:pointer;border:1px solid var(--divider);border-radius:10px;background:var(--sheet);color:var(--ink);font-weight:750;padding:8px 12px}button:focus-visible,input:focus-visible{outline:3px solid #8eabf3;outline-offset:3px}label{display:block;font-size:.875rem;font-weight:750;margin-top:16px}input{display:block;width:100%;min-height:48px;margin-top:6px;padding:0 12px;border:1px solid var(--divider);border-radius:10px;background:var(--sheet);color:var(--ink)}.password-wrap{position:relative}.password-wrap input{padding-right:72px}.show-password{position:absolute;right:4px;bottom:4px;min-height:40px;border:0;color:var(--cobalt)}.alert{min-height:24px;margin:16px 0 0;color:var(--danger);font-size:.875rem}.submit{width:100%;margin-top:24px;border-color:var(--cobalt);background:var(--cobalt);color:#fff}.submit:disabled{opacity:.6;cursor:wait}@media(max-width:640px){.auth-layout{padding:0;place-items:stretch}.auth-shell{width:100%;border:0;box-shadow:none;grid-template-columns:1fr}.office-intro{min-height:auto;padding:28px}.office-intro h1{font-size:2rem}.office-facts{display:none}.auth-card{padding:28px 24px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
</style></head><body><main class="auth-layout"><section class="auth-shell" aria-labelledby="auth-title"><aside class="office-intro"><div><div class="brand"><span class="mark" aria-hidden="true">G</span>Giraffe</div><p class="kicker">Private Investment Office</p><h1>판단의 근거와 빈칸을 한 화면에서 관리하세요</h1><p>증거, 변화, 미확인 항목을 분리해 차분한 모의투자 결정을 지원합니다.</p></div><p class="office-facts">기록 전용 · 실제 주문 없음<br>중요한 불확실성은 약화하지 않습니다.</p></aside><div class="auth-card"><p class="kicker" style="color:var(--cobalt)">Secure access</p><h2 id="auth-title">모의투자 계획을 시작하세요</h2><p class="muted">개인 판단 오피스에 로그인해 오늘의 근거와 검토 상태를 확인합니다.</p><aside class="paper-note"><strong>모의투자 전용</strong> · 실제 주문이나 증권사 연결은 제공하지 않습니다.</aside>__SIGNUP_UI__<div id="alert" class="alert" role="alert" aria-live="assertive"></div><form id="auth-form"><label for="email">이메일</label><input id="email" type="email" autocomplete="email" required placeholder="name@example.com"><label for="password">비밀번호</label><div class="password-wrap"><input id="password" type="password" autocomplete="current-password" required minlength="8" placeholder="비밀번호를 입력하세요"><button class="show-password" type="button" aria-controls="password" aria-pressed="false">보기</button></div><button id="submit" class="submit" type="submit">로그인</button></form></div></section></main><script>
const $=s=>document.querySelector(s),alertEl=$('#alert'),form=$('#auth-form'),password=$('#password'),submit=$('#submit');__SIGNUP_SCRIPT__$('.show-password').addEventListener('click',e=>{const visible=password.type==='text';password.type=visible?'password':'text';e.currentTarget.textContent=visible?'보기':'숨기기';e.currentTarget.setAttribute('aria-pressed',String(!visible))});form.addEventListener('submit',async e=>{e.preventDefault();alertEl.textContent='';if(!form.checkValidity()){form.reportValidity();return}submit.disabled=true;submit.textContent='처리 중…';try{const r=await fetch(__AUTH_ENDPOINT__,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value.trim(),password:password.value})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'입력 내용을 확인하세요');location.assign('/app')}catch(err){alertEl.textContent=err.message;submit.disabled=false;submit.textContent=__SUBMIT_TEXT__}});
</script></body></html>'''

AUTH_HTML = AUTH_HTML.replace("__SIGNUP_UI__", '<div class="auth-mode" role="group" aria-label="계정 선택"><button id="login-mode" class="mode-button" type="button" aria-pressed="true">로그인</button><button id="signup-mode" class="mode-button" type="button" aria-pressed="false">회원가입</button></div>' if SIGNUP_ENABLED else "").replace("__SIGNUP_SCRIPT__", "let mode='login';const setMode=next=>{mode=next;alertEl.textContent='';password.autocomplete=mode==='signup'?'new-password':'current-password';submit.textContent=mode==='signup'?'회원가입':'로그인';$('#auth-title').textContent=mode==='signup'?'회원가입':'모의투자 계획을 시작하세요';$('#login-mode').setAttribute('aria-pressed',String(mode==='login'));$('#signup-mode').setAttribute('aria-pressed',String(mode==='signup'))};$('#login-mode').addEventListener('click',()=>setMode('login'));$('#signup-mode').addEventListener('click',()=>setMode('signup'));" if SIGNUP_ENABLED else "").replace("__AUTH_ENDPOINT__", "mode==='signup'?'/api/signup':'/api/login'" if SIGNUP_ENABLED else "'/api/login'").replace("__SUBMIT_TEXT__", "mode==='signup'?'회원가입':'로그인'" if SIGNUP_ENABLED else "'로그인'")

APP_HTML = Path(__file__).with_name('decision_card_app.html').read_text(encoding='utf-8')
PROTOTYPE_HTML = Path(__file__).with_name('prototype.html').read_text(encoding='utf-8')
